-- Cobros con Mercado Pago (Checkout Pro + QR del link de pago).
--
-- Run once in the Supabase SQL Editor. Idempotent.
--
--   cobros_mercadopago -> one row per payment link generated by a seller
--                         (id_usuario = the linked Mercado Pago seller). The
--                         state is updated by the Mercado Pago webhook.
-- Accessed only by the server with the service role key.

CREATE TABLE IF NOT EXISTS public.cobros_mercadopago (
  id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  id_usuario         BIGINT NOT NULL REFERENCES public.usuarios (id) ON DELETE CASCADE,
  id_solicitud       INTEGER REFERENCES public.solicitudes_visita (id_solicitud) ON DELETE SET NULL,
  monto              NUMERIC(12, 2) NOT NULL CHECK (monto > 0),
  descripcion        TEXT,
  external_reference TEXT NOT NULL UNIQUE,
  preference_id      TEXT,
  init_point         TEXT,
  estado             TEXT NOT NULL DEFAULT 'Pendiente'
                     CHECK (estado IN ('Pendiente', 'Aprobado', 'Rechazado', 'Cancelado', 'Expirado')),
  mp_payment_id      TEXT,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS cobros_mercadopago_usuario_idx
  ON public.cobros_mercadopago (id_usuario);

CREATE INDEX IF NOT EXISTS cobros_mercadopago_solicitud_idx
  ON public.cobros_mercadopago (id_solicitud);

-- Defense in depth: same approach as the OAuth tables (service role bypasses RLS).
ALTER TABLE public.cobros_mercadopago ENABLE ROW LEVEL SECURITY;
